set -euo pipefail
if [ ! -d "${XDG_RUNTIME_DIR:-}" ]; then
    export XDG_RUNTIME_DIR="/tmp"
fi

API_DIR="${1:-/home/btw/Projects/SilksongMobileAPI}"
LIB_DIR="${2:-/home/btw/Projects/lib}"

echo "=============================================================================="
echo "==> Silksong Mobile API Directory : $API_DIR"
echo "==> Shared Library Path           : $LIB_DIR"
echo "=============================================================================="

echo "==> Cleaning old duplicate build folders & stray DLLs..."
rm -rf "$API_DIR/bin" "$API_DIR/obj" "$API_DIR/CecilCore/bin" "$API_DIR/CecilCore/obj" "$API_DIR/.tmp_build" "$API_DIR/00_SilksongMobileAPI" "$API_DIR/00_IRIS"
rm -f "$API_DIR/IRIS.dll" "$API_DIR/SilksongMobileAPI.dll" "$API_DIR/SilksongMobileAPI.CecilCore.dll" "$API_DIR/Mono.Cecil.dll"
mkdir -p "$API_DIR/Source" "$API_DIR/CecilCore" "$API_DIR/.tmp_build/CecilCore" "$API_DIR/.tmp_build/Main"


echo "==> Writing Source/BepInExShims.cs..."
cat << 'EOF_SHIMS' > "$API_DIR/Source/BepInExShims.cs"
