            return false;
        }

        public static bool GetKey(KeyCode key)
        {
            if (HasActiveKey(key)) return true;
            if (CheckHeroInputActionKey(key, 0)) return true;
            if (_inNativeInputQuery) return false;
            try
            {
                _inNativeInputQuery = true;
                return Input.GetKey(key);
