        public MonoDetourConfig(int priority = 0, IEnumerable<string> before = null, IEnumerable<string> after = null, string overrideId = null)
        {
            Priority = priority;
            Before = before ?? Array.Empty<string>();
            After = after ?? Array.Empty<string>();
