        public static T FindInVariableArray<T>(T[] orig, string name) where T : NamedVariable
        {
            if (orig == null) return default;
            for (int i = 0; i < orig.Length; i++)
            {
                if (orig[i] != null && orig[i].Name == name)
                    return orig[i];
            }
            return default;
        }

