        public override void Reset()
        {
            FromGameObject = null;
            FromPosition = new FsmVector2 { UseVariable = true };
            Direction = new FsmVector2 { Value = Vector2.up };
            Space = Space.World;
            Distance = 100f;
            StoreDidHit = null;
            StoreHitObject = null;
            StoreHitPoint = null;
            StoreDistance = null;
            StoreHitSpikes = null;
            StoreIsTransitionGate = null;
