                            if (!_bmSpriteCache.ContainsKey(clean) || _bmSpriteCache[clean] == null)
                                _bmSpriteCache[clean] = s;
                            if (!_bmSpriteCache.ContainsKey(s.name) || _bmSpriteCache[s.name] == null)
