                        btTr.GetChild(0).gameObject.SetActive(true);
                    if (btTr.childCount > 1 && btTr.GetChild(1) != null && btTr.GetChild(1).gameObject != null)
                        btTr.GetChild(1).gameObject.SetActive(false);
                }
