                        var cg = hc.configs[i];
                        if (cg != null && cg.Config != null && !cg.Config.ForceBareInventory && !cg.Config.CanPlayNeedolin)
                        {
                            _hcConfigCanPlayNeedolinField.SetValue(cg.Config, true);
