                for (int i = list.Count - 1; i >= 0; i--)
                {
                    var tp = list[i];
                    if (tp == null || tp.gameObject == null)
                    {
                        list.RemoveAt(i);
                        continue;
                    }
                    var sc = tp.gameObject.scene;
                    if (!sc.IsValid() || !sc.isLoaded || !tp.gameObject.activeInHierarchy)
                    {
                        list.RemoveAt(i);
                    }
