                        if (f.name.IndexOf("LegacyRuntime", StringComparison.OrdinalIgnoreCase) >= 0) continue;
                        if (f.name.IndexOf("Trajan", StringComparison.OrdinalIgnoreCase) >= 0 ||
                            f.name.IndexOf("Perpetua", StringComparison.OrdinalIgnoreCase) >= 0 ||
