                    }
                }
                foreach (var mb in FindObjectsOfType<MonoBehaviour>())
                {
                    if (mb == null) continue;
                    string an = mb.GetType().Assembly?.GetName()?.Name ?? "";
                    if (IsExcludedModIdentifier(an))
