                            il.Emit(OpCodes.Stfld, sourceField);

                            il.Emit(OpCodes.Ldarg_0);
                            il.Emit(OpCodes.Ldfld, sourceField);
                            il.Emit(OpCodes.Brfalse_S, lblRet);

                            il.Emit(OpCodes.Ldarg_0);
                            il.Emit(OpCodes.Ldarg_0);
                            il.Emit(OpCodes.Ldfld, sourceField);
