                                il.Emit(OpCodes.Callvirt, mod.ImportReference(getVolMethod));
                                il.Emit(OpCodes.Stfld, volumeField);

                                il.Emit(OpCodes.Ldarg_0);
                                il.Emit(OpCodes.Ldc_I4_0);
                                il.Emit(OpCodes.Stfld, fadingField);
                            }
