"""
cecil_gz = base64.b64decode(CECIL_GZ_B64)
assert len(cecil_gz) == 158505, f"Unexpected cecil_gz length: {len(cecil_gz)}"

with open(core_path, "rb") as f:
    core_gz = gzip.compress(f.read(), compresslevel=9)

def fmt_bytes(b):
    lines = []
    for i in range(0, len(b), 32):
        chunk = ",".join(str(x) for x in b[i:i+32])
        lines.append("            " + chunk)
    return ",\n".join(lines)

with open(out_path, "w", encoding="utf-8") as out:
    out.write("namespace SilksongMobileAPI\n{\n    internal static class EmbeddedPayloads\n    {\n")
    out.write(f"        public static readonly byte[] MonoCecilGZip = new byte[{len(cecil_gz)}]\n        {{\n{fmt_bytes(cecil_gz)}\n        }};\n\n")
    out.write(f"        public static readonly byte[] CecilCoreGZip = new byte[{len(core_gz)}]\n        {{\n{fmt_bytes(core_gz)}\n        }};\n")
    out.write("    }\n}\n")
print(f"Embedded sanitized Mono.Cecil ({len(cecil_gz)} gz bytes -> 353792 raw bytes) + CecilCore ({len(core_gz)} gz bytes).")
EOF_PY_EMBED


echo "==> Writing SilksongMobileAPI.csproj..."
