EOF_MAIN_CSPROJ

echo "==> Building Stage 2: IRIS.dll (Release)..."
dotnet build "$API_DIR/SilksongMobileAPI.csproj" -c Release /p:NuGetAudit=false

mkdir -p "$API_DIR/00_IRIS"
cp -f "$API_DIR/.tmp_build/Main/IRIS.dll" "$API_DIR/00_IRIS/IRIS.dll"
cat << 'EOF_PLUGIN_JSON' > "$API_DIR/00_IRIS/plugin.json"
{
  "Name": "IRIS v2.9.6.16",
  "Description": "IRIS — Runtime Cecil IL Rewriter + HybridCLR Dynamic Hook Adapter + PlayMaker FSM & Prepatcher Bridge for Silksong Mobile.",
  "EntryDLL": "IRIS.dll",
  "DepDLLs": [],
  "DepPlugins": []
}
EOF_PLUGIN_JSON

# Remove intermediate build directories so ONLY $API_DIR/00_IRIS/ contains IRIS.dll
rm -rf "$API_DIR/.tmp_build" "$API_DIR/obj" "$API_DIR/CecilCore/obj"

echo "=============================================================================="
echo "Build Complete (IRIS v2.9.6.16)!"
echo "Single deployable folder ready to copy to BepInEx/plugins/:"
echo "  -> $API_DIR/00_IRIS/"
echo "     - IRIS.dll"
echo "     - plugin.json"
echo "=============================================================================="